import json
from typing import Any
from pydantic import BaseModel, ConfigDict, Field, ValidationError

from lfx.custom import Component
from lfx.io import DataInput, MessageTextInput, Output
from lfx.schema import Data, Message


# --- 1. DEFINISI SKEMA PYDANTIC (GAYA FASTAPI) ---

class CaseRequestSchema(BaseModel):
    """Skema untuk Format 2, 3, dan 4 (Request Parameter)."""
    model_config = ConfigDict(extra="allow")

    case_id: str = Field(default="CASE_1_COMPLIANT_CPO", min_length=1)
    dhe_rule_version: str = Field(default="PADG_16_2026", min_length=1)


class ComplianceResultSchema(BaseModel):
    """Skema untuk isi hasil API (memiliki overall_status dan findings)."""
    model_config = ConfigDict(extra="allow")

    overall_status: str
    findings: list[Any]


class FullAPIResponseSchema(BaseModel):
    """Skema untuk Format 1 (Full API Response dengan wrapper result)."""
    model_config = ConfigDict(extra="allow")

    result: ComplianceResultSchema | dict[str, Any]


# --- 2. IMPLEMENTASI DI DALAM COMPONENT ---

class DHEComplianceComponent(Component):
    display_name = "DHE Compliance Parser"
    description = "Parse flexible input atau Data menjadi JSON tervalidasi Pydantic"
    icon = "check-circle"

    inputs = [
        MessageTextInput(
            name="input_text",
            display_name="Chat Message / API JSON",
            required=False,
            info=(
                "Accepted formats:\n"
                '  1) Full API Response JSON (with "result" wrapper)\n'
                '  2) Request JSON: {"case_id": "CASE_1_COMPLIANT_CPO", "dhe_rule_version": "PADG_16_2026"}\n'
                "  3) Space-separated: CASE_1_COMPLIANT_CPO PADG_16_2026\n"
                "  4) Case ID only: CASE_1_COMPLIANT_CPO (defaults to PADG_16_2026)"
            ),
        ),
        DataInput(
            name="api_data",
            display_name="API Request Data (Optional)",
            required=False,
            info="Hubungkan langsung output Data/JSON dari komponen Type Convert atau API Request.",
        ),
    ]

    outputs = [
        Output(display_name="Parsed JSON", name="parsed_json", method="build_json_output"),
    ]

    def _clean_text(self, raw: str) -> str:
        """Bersihkan blok kode markdown dari output LLM menggunakan chr(96) agar aman disalin."""
        text = raw.strip()
        fence = chr(96) * 3  # Representasi aman untuk tiga backtick

        if text.startswith(fence):
            first_newline = text.find("\n")
            if first_newline != -1:
                text = text[first_newline + 1 :]
            else:
                text = text[3:]

        if text.endswith(fence):
            text = text[:-3]

        return text.strip()

    def _validate_dict_with_pydantic(self, parsed: dict) -> dict:
        """Validasi dictionary terhadap 3 kemungkinan skema Pydantic."""
        if "result" in parsed and isinstance(parsed["result"], dict):
            validated = FullAPIResponseSchema.model_validate(parsed)
            res_data = (
                validated.result.model_dump()
                if isinstance(validated.result, BaseModel)
                else validated.result
            )
            return {"_prefetched_result": res_data}

        if "overall_status" in parsed and "findings" in parsed:
            validated = ComplianceResultSchema.model_validate(parsed)
            return {"_prefetched_result": validated.model_dump()}

        if "case_id" in parsed:
            validated = CaseRequestSchema.model_validate(parsed)
            return validated.model_dump()

        return parsed

    def _parse_input(self, raw: str | dict | Data | Message | None) -> dict:
        """Parse flexible input (baik dari DataInput maupun MessageTextInput) dengan Pydantic."""
        if isinstance(raw, Data):
            if isinstance(raw.data, dict) and "text" not in raw.data:
                return self._validate_dict_with_pydantic(raw.data)
            raw = raw.get_text() or ""
        elif isinstance(raw, Message):
            raw = raw.text or ""
        elif isinstance(raw, dict):
            return self._validate_dict_with_pydantic(raw)

        raw_str = self._clean_text(str(raw or ""))
        if not raw_str:
            return CaseRequestSchema().model_dump()

        if raw_str.startswith("{"):
            try:
                parsed = json.loads(raw_str)
                if isinstance(parsed, dict):
                    return self._validate_dict_with_pydantic(parsed)
            except (json.JSONDecodeError, ValidationError) as e:
                msg = f"Format JSON atau skema Pydantic tidak valid: {e}"
                raise ValueError(msg) from e

        parts = raw_str.split()
        return CaseRequestSchema(
            case_id=parts[0] if parts else "CASE_1_COMPLIANT_CPO",
            dhe_rule_version=parts[1] if len(parts) > 1 else "PADG_16_2026",
        ).model_dump()

    def build_json_output(self) -> Data:
        """Method utama untuk mengeluarkan objek Data/JSON Langflow."""
        source_input = self.api_data if self.api_data is not None else self.input_text

        parsed_dict = self._parse_input(source_input)
        self.status = parsed_dict
        return Data(data=parsed_dict)
